// Minimal YAML subset parser compatible with the shapes used by marmite
// config files and front matter: block maps/seqs, flow collections,
// quoted/plain scalars, comments, literal/folded blocks.
use crate::value::Value;

pub fn parse_yaml(src: &str) -> Result<Value, String> {
    let lines: Vec<&str> = src.lines().collect();
    let mut p = Parser { lines, pos: 0 };
    p.parse()
}

struct Parser<'a> {
    lines: Vec<&'a str>,
    pos: usize,
}

fn indent_of(line: &str) -> usize {
    line.len() - line.trim_start_matches(' ').len()
}

/// Strip a trailing ` # comment` from a plain scalar region.
fn strip_comment(s: &str) -> &str {
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'#' && (i == 0 || b[i - 1] == b' ' || b[i - 1] == b'\t') {
            return s[..i].trim_end();
        }
        i += 1;
    }
    s
}

impl<'a> Parser<'a> {
    fn peek_nonempty(&self) -> Option<(usize, &'a str)> {
        let mut i = self.pos;
        while i < self.lines.len() {
            let l = &self.lines[i];
            let t = l.trim_end();
            let stripped = strip_comment(t);
            if !stripped.trim().is_empty() && t.trim() != "---" && t.trim() != "..." {
                return Some((indent_of(l), self.lines[i]));
            }
            i += 1;
        }
        None
    }

    fn parse(&mut self) -> Result<Value, String> {
        // skip document start
        while self.pos < self.lines.len() {
            let t = self.lines[self.pos].trim_end();
            if t.trim() == "---" || strip_comment(t).trim().is_empty() {
                self.pos += 1;
            } else {
                break;
            }
        }
        match self.peek_nonempty() {
            None => Ok(Value::Null),
            Some((indent, _)) => self.parse_block(indent),
        }
    }

    /// Parse a block node at the given indentation level.
    fn parse_block(&mut self, indent: usize) -> Result<Value, String> {
        match self.peek_nonempty() {
            None => Ok(Value::Null),
            Some((ind, line)) => {
                if ind < indent {
                    return Ok(Value::Null);
                }
                let content = line[ind..].trim_end();
                if content.starts_with("- ") || content == "-" {
                    self.parse_seq(ind)
                } else if is_map_line(&line[ind..]) {
                    self.parse_map(ind)
                } else {
                    // scalar (possibly multi-line plain)
                    self.pos = self.lines[self.pos..]
                        .iter()
                        .position(|l| {
                            let t = l.trim_end();
                            !strip_comment(t).trim().is_empty() && t.trim() != "---"
                        })
                        .map(|p| self.pos + p)
                        .unwrap_or(self.lines.len());
                    let line = self.lines[self.pos];
                    self.pos += 1;
                    let s = strip_comment(line[ind..].trim_end()).to_string();
                    Ok(parse_scalar(&s))
                }
            }
        }
    }

    fn parse_seq(&mut self, indent: usize) -> Result<Value, String> {
        let mut items = Vec::new();
        loop {
            // advance to next non-empty
            match self.peek_nonempty() {
                Some((ind, line)) if ind == indent => {
                    let content = line[ind..].trim_end();
                    if !(content.starts_with("- ") || content == "-") {
                        break;
                    }
                }
                _ => break,
            }
            let line = self.lines[self.pos];
            self.pos += 1;
            let content = line[indent..].trim_end();
            let rest = if content == "-" { "" } else { &content[2..] };
            if rest.is_empty() {
                // nested block on following lines
                match self.peek_nonempty() {
                    Some((ind2, _)) if ind2 > indent => {
                        items.push(self.parse_block(ind2)?);
                    }
                    _ => items.push(Value::Null),
                }
            } else if rest.starts_with("- ") || rest == "-" {
                // nested inline seq: "- - a"
                // rewrite current line conceptually: treat rest as a seq line at indent+2
                let synthetic = format!("{}{}", " ".repeat(indent + 2), rest);
                self.lines.insert(self.pos, Box::leak(synthetic.into_boxed_str()));
                items.push(self.parse_block(indent + 2)?);
            } else if is_map_line(rest) {
                // seq item that is a map starting on same line: "- key: val"
                let synthetic = format!("{}{}", " ".repeat(indent + 2), rest);
                self.lines.insert(self.pos, Box::leak(synthetic.into_boxed_str()));
                items.push(self.parse_block(indent + 2)?);
            } else if rest.starts_with('[') || rest.starts_with('{') {
                items.push(parse_flow(rest)?);
            } else if rest.starts_with('|') || rest.starts_with('>') {
                items.push(Value::Str(self.parse_block_scalar(indent, rest)));
            } else {
                let s = strip_comment(rest);
                items.push(parse_scalar(s.trim_end()));
            }
        }
        Ok(Value::Array(items))
    }

    fn parse_map(&mut self, indent: usize) -> Result<Value, String> {
        let mut map: Vec<(String, Value)> = Vec::new();
        loop {
            let (ind, line) = match self.peek_nonempty() {
                Some(x) => x,
                None => break,
            };
            if ind != indent {
                break;
            }
            let content = line[ind..].trim_end();
            if !is_map_line(content) {
                break;
            }
            self.pos += 1;
            let (key, rest) = split_key(content);
            let key = parse_key(key);
            let rest = rest.trim_start();
            let value = if rest.is_empty() {
                match self.peek_nonempty() {
                    Some((ind2, l2)) if ind2 > indent => self.parse_block(ind2)?,
                    Some((ind2, l2)) if ind2 == indent && {
                        let c = l2[ind2..].trim_end();
                        c.starts_with("- ") || c == "-"
                    } =>
                    {
                        // seq at same indent as key belongs to the key
                        self.parse_seq(indent)?
                    }
                    _ => Value::Null,
                }
            } else if rest.starts_with('[') || rest.starts_with('{') {
                parse_flow(rest)?
            } else if rest.starts_with('|') || rest.starts_with('>') {
                Value::Str(self.parse_block_scalar(indent, rest))
            } else {
                let s = strip_comment(rest);
                parse_scalar(s.trim_end())
            };
            if let Some(e) = map.iter_mut().find(|(k, _)| *k == key) {
                e.1 = value;
            } else {
                map.push((key, value));
            }
        }
        Ok(Value::Map(map))
    }

    /// literal | or folded > block scalar; header already parsed (rest given).
    fn parse_block_scalar(&mut self, parent_indent: usize, header: &str) -> String {
        let folded = header.starts_with('>');
        let strip = header.contains('-');
        let keep = header.contains('+');
        let mut collected: Vec<String> = Vec::new();
        let mut block_indent: Option<usize> = None;
        while self.pos < self.lines.len() {
            let line = self.lines[self.pos];
            if line.trim().is_empty() {
                collected.push(String::new());
                self.pos += 1;
                continue;
            }
            let ind = indent_of(line);
            if ind <= parent_indent {
                break;
            }
            let bi = *block_indent.get_or_insert(ind);
            if ind < bi {
                break;
            }
            collected.push(line[bi.min(line.len())..].trim_end().to_string());
            self.pos += 1;
        }
        // trim trailing empties
        while collected.last().map(|s| s.is_empty()) == Some(true) {
            collected.pop();
        }
        let mut out = if folded {
            collected.join(" ")
        } else {
            collected.join("\n")
        };
        if keep {
            out.push('\n');
        } else if !strip {
            out.push('\n');
        }
        out
    }
}

fn is_map_line(s: &str) -> bool {
    split_key_opt(s).is_some()
}

/// Find "key:" split point. Key may be quoted.
fn split_key_opt(s: &str) -> Option<(&str, &str)> {
    let s = s.trim_end();
    if s.starts_with('"') || s.starts_with('\'') {
        let q = s.as_bytes()[0];
        let mut i = 1;
        let b = s.as_bytes();
        while i < b.len() {
            if b[i] == q {
                if q == b'\'' && i + 1 < b.len() && b[i + 1] == b'\'' {
                    i += 2;
                    continue;
                }
                if q == b'"' && b[i - 1] == b'\\' {
                    i += 1;
                    continue;
                }
                break;
            }
            i += 1;
        }
        if i < b.len() && b[i] == q {
            let rest = &s[i + 1..];
            if let Some(r) = rest.strip_prefix(':') {
                if r.is_empty() || r.starts_with(' ') {
                    return Some((&s[..i + 1], r));
                }
            }
        }
        return None;
    }
    // plain key: find ':' followed by space or EOL
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b':' && (i + 1 == b.len() || b[i + 1] == b' ') {
            return Some((&s[..i], &s[i + 1..]));
        }
        // stop if we hit chars invalid in plain key context
        i += 1;
    }
    None
}

fn split_key(s: &str) -> (&str, &str) {
    split_key_opt(s).unwrap_or((s, ""))
}

fn parse_key(k: &str) -> String {
    let k = k.trim();
    if (k.starts_with('"') && k.ends_with('"') && k.len() >= 2)
        || (k.starts_with('\'') && k.ends_with('\'') && k.len() >= 2)
    {
        if let Value::Str(s) = parse_scalar(k) {
            return s;
        }
    }
    k.to_string()
}

/// Parse flow collection [a, b] or {k: v} (possibly nested).
fn parse_flow(s: &str) -> Result<Value, String> {
    let mut chars: Vec<char> = s.chars().collect();
    let mut pos = 0;
    let v = parse_flow_value(&mut chars, &mut pos)?;
    Ok(v)
}

fn skip_ws(c: &[char], pos: &mut usize) {
    while *pos < c.len() && (c[*pos] == ' ' || c[*pos] == '\t') {
        *pos += 1;
    }
}

fn parse_flow_value(c: &[char], pos: &mut usize) -> Result<Value, String> {
    skip_ws(c, pos);
    if *pos >= c.len() {
        return Ok(Value::Null);
    }
    match c[*pos] {
        '[' => {
            *pos += 1;
            let mut items = Vec::new();
            loop {
                skip_ws(c, pos);
                if *pos >= c.len() {
                    break;
                }
                if c[*pos] == ']' {
                    *pos += 1;
                    break;
                }
                if c[*pos] == ',' {
                    *pos += 1;
                    continue;
                }
                items.push(parse_flow_value(c, pos)?);
                skip_ws(c, pos);
                if *pos < c.len() && c[*pos] == ',' {
                    *pos += 1;
                }
            }
            Ok(Value::Array(items))
        }
        '{' => {
            *pos += 1;
            let mut map = Vec::new();
            loop {
                skip_ws(c, pos);
                if *pos >= c.len() {
                    break;
                }
                if c[*pos] == '}' {
                    *pos += 1;
                    break;
                }
                if c[*pos] == ',' {
                    *pos += 1;
                    continue;
                }
                let key = parse_flow_scalar(c, pos, true)?;
                skip_ws(c, pos);
                if *pos < c.len() && c[*pos] == ':' {
                    *pos += 1;
                }
                let val = parse_flow_value(c, pos)?;
                map.push((key, val));
                skip_ws(c, pos);
                if *pos < c.len() && c[*pos] == ',' {
                    *pos += 1;
                }
            }
            Ok(Value::Map(map))
        }
        '"' | '\'' => {
            let start = *pos;
            let q = c[*pos];
            *pos += 1;
            while *pos < c.len() {
                if c[*pos] == q {
                    if q == '"' && c[*pos - 1] == '\\' {
                        *pos += 1;
                        continue;
                    }
                    if q == '\'' && *pos + 1 < c.len() && c[*pos + 1] == '\'' {
                        *pos += 2;
                        continue;
                    }
                    *pos += 1;
                    break;
                }
                *pos += 1;
            }
            let raw: String = c[start..*pos].iter().collect();
            Ok(parse_scalar(&raw))
        }
        _ => {
            let s = parse_flow_scalar_raw(c, pos);
            Ok(parse_scalar(&s))
        }
    }
}

fn parse_flow_scalar(c: &[char], pos: &mut usize, _key: bool) -> Result<String, String> {
    skip_ws(c, pos);
    if *pos < c.len() && (c[*pos] == '"' || c[*pos] == '\'') {
        let v = parse_flow_value(c, pos)?;
        return Ok(v.as_str().unwrap_or("").to_string());
    }
    Ok(parse_flow_scalar_raw(c, pos))
}

fn parse_flow_scalar_raw(c: &[char], pos: &mut usize) -> String {
    skip_ws(c, pos);
    let start = *pos;
    while *pos < c.len() && c[*pos] != ',' && c[*pos] != ']' && c[*pos] != '}' {
        *pos += 1;
    }
    let raw: String = c[start..*pos].iter().collect();
    raw.trim().to_string()
}

/// Parse a scalar token into a Value.
pub fn parse_scalar(s: &str) -> Value {
    let s = s.trim_end();
    if s.is_empty() {
        return Value::Null;
    }
    if s.starts_with('"') && s.ends_with('"') && s.len() >= 2 {
        return Value::Str(unescape_double(&s[1..s.len() - 1]));
    }
    if s.starts_with('\'') && s.ends_with('\'') && s.len() >= 2 {
        return Value::Str(s[1..s.len() - 1].replace("''", "'"));
    }
    match s {
        "null" | "Null" | "NULL" | "~" => return Value::Null,
        "true" | "True" | "TRUE" => return Value::Bool(true),
        "false" | "False" | "FALSE" => return Value::Bool(false),
        _ => {}
    }
    // int
    if let Ok(i) = s.parse::<i64>() {
        return Value::Int(i);
    }
    if let Ok(f) = s.parse::<f64>() {
        if s.contains('.') || s.contains('e') || s.contains('E') || s.contains("inf") || s.contains("nan") {
            return Value::Float(f);
        }
    }
    Value::Str(s.to_string())
}

fn unescape_double(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.next() {
                Some('n') => out.push('\n'),
                Some('t') => out.push('\t'),
                Some('r') => out.push('\r'),
                Some('0') => out.push('\0'),
                Some('\\') => out.push('\\'),
                Some('"') => out.push('"'),
                Some('\'') => out.push('\''),
                Some('/') => out.push('/'),
                Some('b') => out.push('\u{8}'),
                Some('f') => out.push('\u{c}'),
                Some('u') => {
                    let hex: String = chars.by_ref().take(4).collect();
                    if let Ok(n) = u32::from_str_radix(&hex, 16) {
                        if let Some(ch) = char::from_u32(n) {
                            out.push(ch);
                        }
                    }
                }
                Some(other) => {
                    out.push('\\');
                    out.push(other);
                }
                None => out.push('\\'),
            }
        } else {
            out.push(c);
        }
    }
    out
}

