        while let Some(c) = chars.next() {
            if c != '%' {
                out.push(c);
                continue;
            }
            match chars.next() {
                Some('Y') => out.push_str(&format!("{:04}", self.year)),
                Some('y') => out.push_str(&format!("{:02}", self.year.rem_euclid(100))),
                Some('m') => out.push_str(&format!("{:02}", self.month)),
                Some('d') => out.push_str(&format!("{:02}", self.day)),
                Some('e') => out.push_str(&format!("{:2}", self.day)),
                Some('H') => out.push_str(&format!("{:02}", self.hour)),
                Some('M') => out.push_str(&format!("{:02}", self.min)),
                Some('S') => out.push_str(&format!("{:02}", self.sec)),
                Some('b') | Some('h') => out.push_str(MONTHS_SHORT[(self.month - 1) as usize]),
                Some('B') => out.push_str(MONTHS_LONG[(self.month - 1) as usize]),
                Some('a') => out.push_str(DAYS_SHORT[self.weekday() as usize]),
                Some('A') => out.push_str(DAYS_LONG[self.weekday() as usize]),
                Some('j') => out.push_str(&format!("{:03}", self.day_of_year())),
                Some('p') => out.push_str(if self.hour < 12 { "AM" } else { "PM" }),
                Some('I') => {
                    let h12 = if self.hour % 12 == 0 { 12 } else { self.hour % 12 };
                    out.push_str(&format!("{:02}", h12));
                }
                Some('s') => out.push_str(&self.timestamp().to_string()),
                Some('z') => out.push_str("+0000"),
                Some('Z') => out.push_str("UTC"),
                Some('F') => out.push_str(&format!(
                    "{:04}-{:02}-{:02}",
                    self.year, self.month, self.day
                )),
                Some('T') => out.push_str(&format!(
                    "{:02}:{:02}:{:02}",
                    self.hour, self.min, self.sec
                )),
                Some('R') => out.push_str(&format!("{:02}:{:02}", self.hour, self.min)),
                Some('+') => out.push_str(&self.to_rfc3339()),
                Some('%') => out.push('%'),
                Some(other) => {
                    out.push('%');
                    out.push(other);
                }
                None => out.push('%'),
            }
        }
        out
    }

    pub fn to_rfc3339(&self) -> String {
        format!(
            "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}+00:00",
            self.year, self.month, self.day, self.hour, self.min, self.sec
        )
    }

    /// RFC2822-ish used in RSS: "Tue, 20 Feb 2024 00:00:00 GMT"
    pub fn to_rfc2822(&self) -> String {
        format!(
            "{}, {:02} {} {:04} {:02}:{:02}:{:02} GMT",
            DAYS_SHORT[self.weekday() as usize],
            self.day,
            MONTHS_SHORT[(self.month - 1) as usize],
            self.year,
            self.hour,
            self.min,
            self.sec
        )
    }

    /// chrono Display for DateTime<Utc>: "2026-08-10 11:27:10.361119777 UTC"
    /// marmite.json shows "... +00:00" style? observed: "2026-08-10 11:27:10.361119777 +00:00"
    pub fn to_display_with_nanos(&self) -> String {
        format!(
            "{:04}-{:02}-{:02} {:02}:{:02}:{:02}.{:09} +00:00",
            self.year,
            self.month,
            self.day,
            self.hour,
            self.min,
            self.sec,
            self.nanos
        )
    }
}

/// Parse a date string following the reference binary's observed rules:
/// - contains 'T': only the date part before 'T' is used (time dropped)
/// - otherwise optional time " HH:MM[:SS[.fraction]]" and optional zone
///   suffix (Z or ±HH:MM) which is ignored (no offset conversion)
/// Accepted: "%Y-%m-%d", "%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S" with
/// fractional seconds and zone suffixes.
pub fn parse_date(s: &str) -> Result<DateTime, String> {
    let s = if let Some(idx) = s.find('T') {
        &s[..idx]
    } else {
        s
    };
    // strip zone suffix
    let mut core = s;
    if core.ends_with('Z') {
        core = &core[..core.len() - 1];
    }
    // strip ±HH:MM / ±HHMM zone (only when it appears after a time part)
    if core.len() > 10 {
        if let Some(pos) = core[10..].find(|c| c == '+' || c == '-') {
            let p = 10 + pos;
            // only strip if what follows looks like a zone (digits)
            let rest = &core[p + 1..];
            if !rest.is_empty() && rest.chars().all(|c| c.is_ascii_digit() || c == ':') {
                core = &core[..p];
            }
        }
    }
    // strip fractional seconds
    if let Some(dot) = core.find('.') {
        core = &core[..dot];
    }
    let mut parts = core.splitn(2, ' ');
    let date_part = parts.next().unwrap_or("");
    let time_part = parts.next();
    let dp: Vec<&str> = date_part.split('-').collect();
    if dp.len() != 3 {
        return Err(format!("premature end of input"));
    }
    let y: i64 = dp[0].parse().map_err(|_| "premature end of input".to_string())?;
    let mo: u32 = dp[1].parse().map_err(|_| "premature end of input".to_string())?;
    let d: u32 = dp[2].parse().map_err(|_| "premature end of input".to_string())?;
    // chrono zero-pads; "2024-3-5" must fail
    if dp[0].len() != 4 || dp[1].len() != 2 || dp[2].len() != 2 {
        return Err("premature end of input".to_string());
    }
    if !(1..=12).contains(&mo) || d < 1 || d > days_in_month(y, mo) {
        return Err("premature end of input".to_string());
    }
    let (mut h, mut mi, mut sec) = (0u32, 0u32, 0u32);
    if let Some(tp) = time_part {
        if !tp.is_empty() {
            let tparts: Vec<&str> = tp.split(':').collect();
            if tparts.len() < 2 || tparts.len() > 3 {
                return Err("premature end of input".to_string());
            }
            h = tparts[0].parse().map_err(|_| "premature end of input".to_string())?;
            mi = tparts[1].parse().map_err(|_| "premature end of input".to_string())?;
            if tparts.len() == 3 {
                sec = tparts[2].parse().map_err(|_| "premature end of input".to_string())?;
            }
        }
    }
    Ok(DateTime {
        year: y,
        month: mo,
        day: d,
        hour: h,
        min: mi,
        sec,
        nanos: 0,
    })
}
